// The review findings pane (issue #108, live in issue #165): `/review-view`
// shows the run's latest code review inside Claude Code.
//
// Read-only. It reads the review through `scripts/run_status.py review`. For a
// record with C1 review runs the view embeds the whole `review_state.v1`
// document, and the pane draws that alone: grades, where-to-look states,
// tools, round and cost, and per-round deltas. For an older record it draws
// today's lens list from the latest `review_result.v2` entry. The pane shows
// those answers and never recomputes them. The only thing it writes is the
// operator's own prompt, when they press a finding's Quote. No acceptance
// decision and no finding edits happen here. The plain fallback on every other
// harness is `run_status.py review`'s table.
//
// - `/review-view` opens the checkout's run; `/review-view #N` issue N's.
// - A state review shows each lens's grade with its blocking and fix-later
//   counts. An old-shape lens row reads met, not met, not run or unscored,
//   with its finding count and its top findings; a lens that did not run, or
//   has no recorded result, says so and never shows a number that could read
//   as a low score.
// - Choosing a lens lists its findings; Quote puts one in the prompt.
// - A Bash call that ran a script which writes review runs reloads the open
//   pane, and so does a change of the run record's modification time, polled
//   every five seconds while the pane is open.
// - The run status band's Review button (issue #105) opens this pane: this
//   module answers the press on `band-review-<issue>` itself, because a
//   plugin's own `$.command.run` never reaches its own command hook.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { SagaReviewView } from '../types/index.d.ts'
import { fitTables } from './plan-sections.ts'
import {
  costLine,
  findingHeading,
  findingLine,
  findingsFor,
  findingText,
  gradeLabel,
  lensLabel,
  OTHER_FINDINGS,
  quoteText,
  reviewHeading,
  roundLabel,
  stateFindingHeading,
  stateFindingText,
  stateHeading,
  stateLensFindings,
  stateQuoteText,
  whereToLookLabel,
} from './review-findings.ts'
import { isStateReview, readEitherReviewWith } from './run-record.ts'
import type { ReviewViewQuery } from './run-record.ts'

/** The pane's id, and the `requestId` its `ui.render` hook matches. */
export const REVIEW_PANE = 'saga-review'

/** The run status band's Review button, `band-review-<issue>` (issue #105). */
export const BAND_REVIEW_ELEMENT = /^band-review-\d+$/

/** How often an open pane checks the run record's modification time. */
export const REVIEW_POLL_MS = 5_000

/** A Bash command that ran a script which writes review runs or answers. */
const WRITES_REVIEW = /\b(review_result|review_command|review_state)\.py\b/

const reviewView = atom({ plugin: 'saga', key: 'reviewView' } as const, null)
const reviewLens = atom({ plugin: 'saga', key: 'reviewLens' } as const, null)
const reviewMtimeMs = atom({ plugin: 'saga', key: 'reviewMtimeMs' } as const, 0)

/** The run record's modification time, or 0 when it cannot be read. */
async function recordMtime($: EngineInterface, view: SagaReviewView): Promise<number> {
  if (view.record_path === null) return 0
  try {
    return (await $.fs.stat(view.record_path)).mtimeMs
  } catch {
    return 0
  }
}

/** Read the review again for the shown issue, keeping the reader on their lens when it is still there. */
async function reloadReview($: EngineInterface, shown: SagaReviewView): Promise<void> {
  const query: ReviewViewQuery = { repoRoot: shown.repo_root }
  if (shown.issue !== null) query.issue = shown.issue
  const ran = await readEitherReviewWith((argv) => $.process.run(argv), $.plugin.root, query)
  // A record caught mid-write keeps its last good review on screen.
  if (!ran.ok || ran.view.review === null) return
  const view = ran.view
  await update($, reviewView, () => view)
  const mtime = await recordMtime($, view)
  await update($, reviewMtimeMs, () => mtime)
  const lens = await read($, reviewLens)
  const review = view.review
  if (lens !== null && review !== null && lens !== OTHER_FINDINGS && !review.lenses.some((one) => one.lens === lens)) {
    await update($, reviewLens, () => null)
  }
}

async function isOpen($: EngineInterface): Promise<boolean> {
  const panes = await $.ui.panes()
  return panes.some((pane) => pane.id === REVIEW_PANE)
}

/** Put text in the operator's prompt, saying so when the prompt cannot take it. */
async function fillPrompt($: EngineInterface, text: string): Promise<void> {
  const filled = await $.prompt.fill({ text, mode: 'insert' })
  if (!filled.isFilled) $.ui.toast('review-view: the prompt cannot take text right now')
}

/**
 * Open the pane on `args` as `/review-view` takes them: nothing or `#N`.
 * Says what it did; `isOpened` is false when there was nothing to open.
 */
async function openReviewView($: EngineInterface, args: string): Promise<{ text: string; isOpened: boolean }> {
  const cwd = await $.session.cwd()
  const target = args.trim()
  const issueArg = /^#?(\d+)$/.exec(target)
  if (target !== '' && issueArg === null) return { text: 'review-view: name an issue, as in /review-view #108', isOpened: false }
  const query: ReviewViewQuery = { repoRoot: cwd }
  if (issueArg !== null) query.issue = Number(issueArg[1])

  const ran = await readEitherReviewWith((argv) => $.process.run(argv), $.plugin.root, query)
  if (!ran.ok) return { text: `review-view: could not read the review (${ran.reason}): ${ran.detail}`, isOpened: false }
  const view = ran.view
  const review = view.review
  if (view.issue === null) return { text: 'review-view: no saga run for this checkout. Name one: /review-view #N', isOpened: false }
  if (review === null) return { text: `review-view: no review result recorded for #${view.issue}.`, isOpened: false }

  await update($, reviewView, () => view)
  await update($, reviewLens, () => null)
  const mtime = await recordMtime($, view)
  await update($, reviewMtimeMs, () => mtime)
  if (isStateReview(review)) {
    await $.ui.open({ id: REVIEW_PANE, title: `Review · #${view.issue} round ${review.round}` })
    const blocking = review.lenses.reduce((sum, lens) => sum + lens.blocking, 0)
    const fixLater = review.lenses.reduce((sum, lens) => sum + lens.fix_later, 0)
    return {
      text: `review-view: #${view.issue} round ${review.round}, ${review.outcome}, ${review.lenses.length} lenses, ${blocking} blocking, ${fixLater} fix later.`,
      isOpened: true,
    }
  }
  await $.ui.open({ id: REVIEW_PANE, title: `Review · #${view.issue} cycle ${review.cycle}` })
  const findings = review.lenses.reduce((sum, lens) => sum + lens.finding_count, 0) + review.unattributed_findings.length
  return {
    text: `review-view: #${view.issue} cycle ${review.cycle}, ${review.outcome}, ${review.lenses.length} lenses, ${findings} findings.`,
    isOpened: true,
  }
}

export function registerReviewPane(on: On): void {
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    await $.command.register({
      name: 'review-view',
      description: 'Show the latest saga code review, lens by lens, in a pane',
      argumentHint: '[#issue]',
      immediate: true,
    })

    // Catches a review written by another session: a stat, never a read of the record.
    async function poll(): Promise<void> {
      const view = await read($, reviewView)
      if (view === null || view.record_path === null) return
      if (!(await isOpen($))) return
      const mtime = await recordMtime($, view)
      if (mtime === 0 || mtime === (await read($, reviewMtimeMs))) return
      await reloadReview($, view)
    }
    $.clock.every(REVIEW_POLL_MS, () => {
      void poll()
    })

    return next(e)
  })

  on('command.run', { command: 'review-view' }, async ($, e) => {
    const opened = await openReviewView($, e.args)
    return { text: opened.text }
  })

  // The run status band's Review button (issue #105): a press on `band-review-N` opens #N's review.
  on('ui.press', { plugin: 'saga', element: BAND_REVIEW_ELEMENT }, async ($, e) => {
    const issue = /(\d+)$/.exec(e.element)?.[1] ?? ''
    const opened = await openReviewView($, `#${issue}`)
    if (!opened.isOpened) $.ui.toast(opened.text)
    return { element: e.element }
  })

  // `review_result.py` writing a result reloads the open pane at once.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny !== undefined || ran.isError === true) return ran
    if (!WRITES_REVIEW.test(e.command)) return ran
    const view = await read($, reviewView)
    if (view === null || !(await isOpen($))) return ran
    await reloadReview($, view)
    return ran
  })

  on('ui.render', { component: 'Pane', requestId: REVIEW_PANE }, async ($, e) => {
    const { Box, Button, Markdown, Text } = $.ui.resolve(e)
    const view = await read($, reviewView)
    const review = view?.review ?? null
    if (view === null || review === null) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No review loaded. Run /review-view or /review-view #issue.</Text>
        </Box>
      )
    }

    const lens = await read($, reviewLens)
    if (isStateReview(review)) {
      const state = review.state
      if (lens === null) {
        const others = stateLensFindings(state, OTHER_FINDINGS)
        const ran = Object.entries(state.tools.ran)
        return (
          <Box flexDirection="column">
            <Text dimColor>{stateHeading(view.issue, review)}</Text>
            <Text bold>Grades</Text>
            {state.lenses.map((one) => (
              <Box key={`row-${one.lens}`} flexDirection="column">
                <Button key={`lens-${one.lens}`} label={gradeLabel(one)} plain onPress={() => update($, reviewLens, () => one.lens)} />
              </Box>
            ))}
            {others.length > 0 && (
              <Button
                key="lens-other"
                label={`${OTHER_FINDINGS}  ${others.length} finding${others.length === 1 ? '' : 's'}`}
                plain
                onPress={() => update($, reviewLens, () => OTHER_FINDINGS)}
              />
            )}
            <Text bold>Where to look</Text>
            {state.where_to_look.length === 0 && <Text dimColor>None.</Text>}
            {state.where_to_look.map((item, i) => (
              <Box key={`wtl-${i}`}>
                <Text dimColor>{whereToLookLabel(item)}</Text>
              </Box>
            ))}
            <Text bold>Tools</Text>
            {ran.map(([name, version]) => (
              <Box key={`tool-${name}`}>
                <Text dimColor>{`${name} ${version}`}</Text>
              </Box>
            ))}
            {state.tools.missing_notice !== null && <Text>{state.tools.missing_notice}</Text>}
            {state.tools.missing_notice === null && state.tools.missing_tools.length > 0 && (
              <Text dimColor>{`missing: ${state.tools.missing_tools.join(', ')}`}</Text>
            )}
            <Text bold>{`Round ${state.round}`}</Text>
            <Text dimColor>{costLine(state.cost)}</Text>
            {state.rounds.map((round) => (
              <Box key={`round-${round.round}`} flexDirection="column">
                <Text>{roundLabel(round)}</Text>
                {round.new_blocking.map((id) => (
                  <Box key={`new-${id}`}>
                    <Text dimColor>{`  + ${id}`}</Text>
                  </Box>
                ))}
                {round.cleared_blocking.map((id) => (
                  <Box key={`cleared-${id}`}>
                    <Text dimColor>{`  - ${id}`}</Text>
                  </Box>
                ))}
                {round.new_blocking.length === 0 && round.cleared_blocking.length === 0 && (
                  <Text dimColor>  nothing added or cleared</Text>
                )}
              </Box>
            ))}
          </Box>
        )
      }
      const stateFindings = stateLensFindings(state, lens)
      const shownGrade = state.lenses.find((one) => one.lens === lens)
      return (
        <Box flexDirection="column">
          <Button key="back" label="Grades" onPress={() => update($, reviewLens, () => null)} />
          <Text bold>{shownGrade === undefined ? lens : gradeLabel(shownGrade)}</Text>
          {stateFindings.length === 0 && <Text dimColor>No findings.</Text>}
          {stateFindings.map((finding, i) => (
            <Box key={`finding-${i}`} flexDirection="column">
              <Text key={`heading-${i}`}>{stateFindingHeading(finding)}</Text>
              <Markdown
                key={`text-${i}`}
                text={e.surface === 'terminal' ? fitTables(stateFindingText(finding), e.props.bodyColumns) : stateFindingText(finding)}
              />
              <Button key={`quote-${i}`} label="Quote" onPress={() => fillPrompt($, stateQuoteText(finding))} />
            </Box>
          ))}
        </Box>
      )
    }
    if (lens === null) {
      const others = review.unattributed_findings
      return (
        <Box flexDirection="column">
          <Text dimColor>{reviewHeading(view.issue, review)}</Text>
          {review.lenses.length === 0 && <Text>This review has no lens results.</Text>}
          {review.lenses.map((one) => (
            <Box key={`row-${one.lens}`} flexDirection="column">
              <Button key={`lens-${one.lens}`} label={lensLabel(one)} plain onPress={() => update($, reviewLens, () => one.lens)} />
              {one.top.map((finding, i) => (
                <Text key={`top-${one.lens}-${i}`} dimColor>
                  {`  ${findingLine(finding)}`}
                </Text>
              ))}
            </Box>
          ))}
          {others.length > 0 && (
            <Button
              key="lens-other"
              label={`${OTHER_FINDINGS}  ${others.length} finding${others.length === 1 ? '' : 's'}`}
              plain
              onPress={() => update($, reviewLens, () => OTHER_FINDINGS)}
            />
          )}
        </Box>
      )
    }

    const findings = findingsFor(review, lens)
    const shown = review.lenses.find((one) => one.lens === lens)
    return (
      <Box flexDirection="column">
        <Button key="back" label="Lenses" onPress={() => update($, reviewLens, () => null)} />
        <Text bold>{shown === undefined ? lens : lensLabel(shown)}</Text>
        {findings.length === 0 && <Text dimColor>No findings.</Text>}
        {findings.map((finding, i) => (
          <Box key={`finding-${i}`} flexDirection="column">
            <Text key={`heading-${i}`}>{findingHeading(finding)}</Text>
            <Markdown
              key={`text-${i}`}
              text={e.surface === 'terminal' ? fitTables(findingText(finding), e.props.bodyColumns) : findingText(finding)}
            />
            <Button key={`quote-${i}`} label="Quote" onPress={() => fillPrompt($, quoteText(lens, finding))} />
          </Box>
        ))}
      </Box>
    )
  })
}

files.mods/setup-pane.tsx:
// The setup pane (issue #165): C3's survey rows with a checkbox each, an
// Install button that runs the ticked tools, and the first-session offer.
//
// The model calls the tool `mcp__saga__setup` with the checkout. The tool runs
// `saga_setup.py survey --format json` and draws the pane from that document
// alone: each tool's id, status, lens and pinned version with a checkbox,
// pre-ticked when the status is not installed. A row with no install command
// has no checkbox and shows the script's install sentence instead. Install
// runs one `install --tools <id>` call per ticked tool, in pane order,
// showing each row's progress, and stops at the first failure; Done returns
// the installed and failed lists to the model. Dismissed, timed-out and the
// error paths match the merge pane: closing records nothing, and a timeout
// returns timed-out with whatever already installed left installed.
//
// The offer: when C3's machine record shows setup has never run — and neither
// the machine record nor the mod's `$.store` remembers the offer — the first
// session start toasts `Run /saga:setup to check this machine's tools.`, then
// records the offer in the machine record through `record-offer` and in the
// store, machine first. The offer check never runs `survey`: the survey
// persists the machine record with `ran` set, so checking with it would mark
// setup run. Any store failure suppresses the offer path without throwing, so
// a suite or build without the store stays silent and green.
//
// Waiting for a person: the tool waits on `$.process.run(['sleep', '1'])`, one
// second at a time, up to WAIT_CAP_SECONDS (LEARNINGS.md, 2026-10-04).

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'
import type { SagaSetupOutcome, SagaSetupSurvey, SagaSetupToolRow } from '../types/index.d.ts'
import {
  readOfferStatusWith,
  readSetupSurveyWith,
  setupInstallArgv,
  setupRecordOfferArgv,
} from './run-record.ts'

/** The pane's id. */
export const PANE = 'saga-setup'

/** The tool's short name; the model calls it as `mcp__saga__setup`. */
export const TOOL = 'setup'

/** How long the tool waits for the operator before it returns timed-out: thirty minutes. */
export const WAIT_CAP_SECONDS = 1800

/** How long one tool install may take. */
const INSTALL_TIMEOUT_MS = 300_000

/** The `$.store` key remembering the setup offer. */
export const OFFER_STORE_KEY = 'setup_offered'

/** The offer toasted once, on the first session of a machine setup never ran on. */
export const OFFER_TEXT = "Run /saga:setup to check this machine's tools."

const setup = atom({ plugin: 'saga', key: 'setupReview' } as const, null)

/**
 * The outcome of the setup in flight. A module value, not `$.state`: the
 * waiting hook reads it between its sleeps, and a state read inside one
 * dispatch sees one frozen moment. A hot reload drops it with the pane.
 */
let outcome: SagaSetupOutcome | undefined

/** Whether a setup pane is open. One setup at a time. */
let active = false

/**
 * The Install run's epoch. Each Install bumps it and orphans any older loop,
 * so a loop outlived by its pane can never mark another setup's rows.
 */
let installEpoch = 0

// ---------------------------------------------------------------------------
// Pure helpers: no `$`, so a test calls them directly
// ---------------------------------------------------------------------------

/** The ticks the pane opens with: every installable row whose status is not installed. */
export function initialTicks(survey: SagaSetupSurvey): Record<string, boolean> {
  const ticked: Record<string, boolean> = {}
  for (const row of survey.tools) {
    ticked[row.id] = row.has_install && row.status !== 'installed'
  }
  return ticked
}

/** The ticked installable ids, in survey order: exactly what Install passes, one argv each. */
export function tickedIds(survey: SagaSetupSurvey, ticked: Record<string, boolean>): string[] {
  return survey.tools.filter((row) => row.has_install && ticked[row.id] === true).map((row) => row.id)
}

/** One row's checkbox label: the tick box, id, status and lens. */
export function rowLabel(row: SagaSetupToolRow, ticked: boolean): string {
  return `${ticked ? '[x]' : '[ ]'} ${row.id}  ${row.status}  ${row.lens}`
}

/** The last lines of a row's install output that the pane shows. */
export function shownOutput(output: string): string {
  return output.length > 2000 ? `\u2026${output.slice(-2000)}` : output
}

// ---------------------------------------------------------------------------
// The hooks
// ---------------------------------------------------------------------------

export function registerSetupPane(on: On): void {
  // The matcher is load-bearing: the engine refuses a second matcher-less
  // `session.start` registration, and admission's holds that one slot.
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    await $.tool.register({
      name: TOOL,
      description:
        "Opens saga's setup pane for a checkout: C3's surveyed tool rows with a checkbox each, and an " +
        'Install button that runs the ticked tools through scripts/saga_setup.py and shows live progress. ' +
        'Returns status submitted (with the installed and failed ids), dismissed, not-placed, unavailable, ' +
        'nothing-to-review, timed-out or error; on anything but submitted, print the survey table and ask ' +
        'which tools to install instead.',
      inputSchema: {
        type: 'object',
        properties: {
          repo: { type: 'string', description: 'The checkout to set up; defaults to the session directory.' },
        },
      },
    })
    const out = await next(e)
    await maybeOfferSetup($)
    return out
  })

  on('tool.call', { tool: 'mcp__saga__setup' }, async ($, e, next) => {
    if (active) {
      return { result: { status: 'error', reason: 'a setup pane is already open' } }
    }
    const surfaces = await $.session.surfaces()
    if (!surfaces.some((surface) => surface === 'terminal' || surface === 'desktop')) {
      return {
        result: { status: 'unavailable', reason: 'no terminal or desktop surface is attached to draw the pane' },
      }
    }
    const cwd = await $.session.cwd()
    const input = (e as { repo?: unknown }).repo
    const repo = typeof input === 'string' && input !== '' ? input : cwd

    const read = await readSetupSurveyWith((argv) => $.process.run(argv), $.plugin.root, repo)
    if (!read.ok) {
      return { result: { status: 'error', reason: `saga_setup survey failed (${read.reason}): ${read.detail}` } }
    }
    if (read.survey.tools.length === 0) {
      return { result: { status: 'nothing-to-review' } }
    }

    active = true
    outcome = undefined
    await update($, setup, () => ({
      repo,
      survey: read.survey,
      ticked: initialTicks(read.survey),
      progress: null,
      error: null,
    }))
    try {
      const opened = await $.ui.open({ id: PANE, title: 'Setup', focus: true })
      if (!opened.isPlaced) {
        return { result: { status: 'not-placed', reason: opened.reason } }
      }
      let waited = 0
      while (outcome === undefined && !next.signal.aborted && waited < WAIT_CAP_SECONDS) {
        await $.process.run(['sleep', '1'])
        waited += 1
      }
      return { result: outcome ?? { status: next.signal.aborted ? 'dismissed' : 'timed-out' } }
    } catch (err) {
      return { result: { status: 'error', reason: `the setup pane failed: ${String(err)}` } }
    } finally {
      active = false
      outcome = undefined
      installEpoch += 1
      await $.ui.close({ id: PANE })
      await update($, setup, () => null)
    }
  })

  on('ui.close', { id: PANE }, ($, e, next) => {
    // Every close but the tool's own after an outcome: the operator's close mark or Escape.
    if (active && outcome === undefined) outcome = { status: 'dismissed' }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const state = await read($, setup)
    if (e.surface !== 'terminal' && e.surface !== 'desktop') {
      const { Text } = $.ui.resolve(e)
      return <Text>Answer the setup pane in the terminal or the desktop app.</Text>
    }
    const { Box, Button, Text } = $.ui.resolve(e)
    if (state === null) {
      return <Text dimColor>No setup is open.</Text>
    }
    const { repo, survey } = state

    const toggle = (id: string) =>
      update($, setup, (current) => {
        if (!current || current.progress !== null) return current
        const row = current.survey.tools.find((one) => one.id === id)
        if (!row || !row.has_install) return current
        return { ...current, ticked: { ...current.ticked, [id]: current.ticked[id] !== true }, error: null }
      })
    const setError = (error: string) => update($, setup, (current) => current && { ...current, error })
    const markRow = (id: string, progress: { state: 'queued' | 'installing' | 'done' | 'failed'; output: string }) =>
      update($, setup, (current) => {
        if (!current || current.progress === null) return current
        return { ...current, progress: { ...current.progress, [id]: progress } }
      })

    const install = async () => {
      const current = await read($, setup)
      if (!current || current.repo !== repo || current.progress !== null) return
      // Bumped after the guards, so a second press that finds work started
      // returns without orphaning the loop already running.
      const epoch = ++installEpoch
      const ids = tickedIds(current.survey, current.ticked)
      if (ids.length === 0) {
        await setError('Tick at least one tool with an install command.')
        return
      }
      const progress: Record<string, { state: 'queued' | 'installing' | 'done' | 'failed'; output: string }> = {}
      for (const id of ids) progress[id] = { state: 'queued', output: '' }
      await update($, setup, (shown) => (shown ? { ...shown, progress, error: null } : shown))
      for (const id of ids) {
        if (epoch !== installEpoch) return
        await markRow(id, { state: 'installing', output: '' })
        let ran
        try {
          ran = await $.process.run(setupInstallArgv($.plugin.root, id, repo), { timeoutMs: INSTALL_TIMEOUT_MS })
        } catch (err) {
          if (epoch !== installEpoch) return
          await markRow(id, { state: 'failed', output: String(err) })
          return
        }
        if (epoch !== installEpoch) return
        const output = `${ran.stdout}${ran.stderr}`.trim()
        if (ran.exitCode !== 0) {
          await markRow(id, { state: 'failed', output: output === '' ? `install exited ${ran.exitCode}` : output })
          return
        }
        await markRow(id, { state: 'done', output })
      }
    }
    const done = async () => {
      const current = await read($, setup)
      if (!current) return
      const installed: string[] = []
      const failed: string[] = []
      for (const [id, row] of Object.entries(current.progress ?? {})) {
        if (row.state === 'done') installed.push(id)
        else if (row.state === 'failed') failed.push(id)
      }
      outcome = { status: 'submitted', installed, failed }
      await $.ui.close({ id: PANE })
    }
    const dismiss = async () => {
      outcome = { status: 'dismissed' }
      await $.ui.close({ id: PANE })
    }

    const running = state.progress !== null && Object.values(state.progress).some((row) => row.state === 'installing' || row.state === 'queued')
    return (
      <Box flexDirection="column" width={e.props.bodyColumns}>
        <Text bold>Tools</Text>
        {survey.tools.map((row) => (
          <Box key={`row:${row.id}`} flexDirection="column">
            {row.has_install ? (
              <Button
                key={`tick:${row.id}`}
                label={rowLabel(row, state.ticked[row.id] === true)}
                plain
                onPress={() => toggle(row.id)}
              />
            ) : (
              <Text dimColor>{`${row.id}  ${row.status}  ${row.lens}`}</Text>
            )}
            <Text dimColor>
              {`  ${row.version ?? 'no version'}  pinned ${row.pinned_version}${row.has_install ? '' : `  ${row.install ?? 'no install command'}`}`}
            </Text>
            {state.progress?.[row.id] && (
              <Text key={`progress:${row.id}`} dimColor>
                {`  ${state.progress[row.id]?.state}: ${shownOutput(state.progress[row.id]?.output ?? '')}`}
              </Text>
            )}
          </Box>
        ))}
        {state.error !== null && (
          <Box key="error" marginTop={1}>
            <Text color="red" wrap="wrap">
              {state.error}
            </Text>
          </Box>
        )}
        <Box key="actions" flexDirection="row" columnGap={2} marginTop={1}>
          <Button key="install" label={running ? 'Installing…' : 'Install'} variant="primary" onPress={() => install()} />
          <Button key="done" label="Done" hotkey="d" onPress={() => done()} />
          <Button key="dismiss" label="Dismiss" role="dismiss" onPress={() => dismiss()} />
        </Box>
      </Box>
    )
  })
}

/**
 * Toast the setup offer once, on the first session of a machine setup never
 * ran on. The store is read first: when it remembers the offer the script is
 * never called. Any store failure suppresses the path without throwing.
 */
async function maybeOfferSetup($: EngineInterface): Promise<void> {
  let remembered: unknown
  try {
    remembered = await $.store.get(OFFER_STORE_KEY)
  } catch {
    return
  }
  if (remembered === true) return
  const read = await readOfferStatusWith((argv) => $.process.run(argv), $.plugin.root)
  if (!read.ok) {
    await $.ui.toast(`saga: could not read the machine record (${read.reason}): ${read.detail}`)
    return
  }
  if (read.status.ran || read.status.offered) return
  await $.ui.toast(OFFER_TEXT)
  let recorded
  try {
    recorded = await $.process.run(setupRecordOfferArgv($.plugin.root))
  } catch (err) {
    await $.ui.toast(`saga: could not record the setup offer: ${String(err)}`)
    return
  }
  if (recorded.exitCode !== 0) {
    const stderr = recorded.stderr.trim()
    await $.ui.toast(`saga: could not record the setup offer: ${stderr === '' ? `record-offer exited ${recorded.exitCode}` : stderr}`)
    return
  }
  try {
    await $.store.set(OFFER_STORE_KEY, true)
  } catch {
    // The machine record already remembers; a store that fails just costs one
    // offer-status call next session.
  }
}

files.mods/usage-capture.ts:
// Live token capture (issue #107): what each model request of a unit session
// costs, appended to that unit's row of the run record as the session runs.
//
// Saga's scripts own the record; this mod only collects and hands over.
//
// - At session start it asks `run_status.py unit-for` which unit row the
//   session's directory is working: the row whose worktree it is, else the row
//   whose branch is checked out there. No row, and the mod records nothing:
//   no timer, no queue, no write. The coordinator in the primary checkout is
//   such a session.
// - Every model request (`turn.step`), on the main thread and in every
//   subagent's loop, adds its usage to a bucket in `$.state`: one bucket per
//   model session, role, model and effort, the identity of a `usage add` entry.
//   `turn.step` rather than `turn.complete`, because only the request carries
//   the effort it asked for, and a subagent's turns complete inside the
//   parent's.
// - Every minute, and at session end, each bucket is written through
//   `run_record.py usage add`, the one portable writer, which takes the
//   record's lock. One process per bucket per minute, never one per request.
//   A failed write keeps its bucket for the next tick; a written one is
//   subtracted, so requests that landed during the write are kept.
//
// Claude Code reports cache writes as one count, without the five-minute and
// one-hour split the record prices apart. They are recorded as one-hour writes,
// the dearer rate, so a report built on them can overstate cache-write spend
// but never understate it (`references/run-record.md`).
//
// The plain fallback on every other harness is the same writer, called by the
// harness's own integration with the counts it reads (`usage add --help`).

import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'

import type { SagaUsageBucket, SagaUsageTarget } from '../types/index.d.ts'
import { KNOWN_RUN_STATUS_SCHEMA, sagaScriptArgv } from './run-record.ts'
import type { ProcessResult } from './run-record.ts'

/** How often the queue is written. */
export const USAGE_FLUSH_MS = 60_000

/** How long one timed write may run before it is abandoned and retried next tick. */
const FLUSH_TIMEOUT_MS = 10_000

/** One write at session end, inside the engine's 1.5-second budget for every hook. */
const END_TIMEOUT_MS = 1_000

/** The vendor every entry this mod writes names. */
export const USAGE_VENDOR = 'claude'

/** The `usage add` flag Claude Code's single cache-write count goes under (see the header). */
export const CACHE_WRITE_FLAG = '--cache-write-1h'

/** The effort a request recorded when its model takes none: `usage add` needs a name. */
export const NO_EFFORT = 'none'

/** A saga role registered as a Claude agent type (`saga:<role>`) records as that role. */
const SAGA_AGENT_TYPE = /^saga:([a-z][a-z0-9-]*)$/

const usageTarget = atom({ plugin: 'saga', key: 'usageTarget' } as const, null)
const usageQueue = atom({ plugin: 'saga', key: 'usageQueue' } as const, [])

/** One request's usage, as `addStep` folds it into the queue. */
export type UsageStep = {
  sessionId: string
  agentId: string | null
  role: string
  model: string
  effort: string
  uncachedInput: number
  cacheRead: number
  cacheWrite: number
  output: number
}

/** The argv that asks which unit row a session at `cwd` is working. */
export function unitForArgv(pluginRoot: string, cwd: string): string[] {
  return sagaScriptArgv(pluginRoot, 'run_status.py', ['--repo-root', cwd, 'unit-for', '--json'])
}

/**
 * The unit `run_status.py unit-for --json` matched, or null. Anything but a
 * clean match of the known view version is null: a mod that cannot tell which
 * unit a session works records nothing rather than guessing.
 */
export function parseUnitFor(ran: ProcessResult): SagaUsageTarget | null {
  if (ran.exitCode !== 0 || ran.isStdoutTruncated) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(ran.stdout)
  } catch {
    return null
  }
  if (typeof parsed !== 'object' || parsed === null) return null
  const view = parsed as { schema?: unknown; match?: unknown }
  if (view.schema !== KNOWN_RUN_STATUS_SCHEMA) return null
  const match = view.match as Partial<SagaUsageTarget> | null | undefined
  if (typeof match !== 'object' || match === null) return null
  const { issue, unit, role, store_root } = match
  if (!Number.isInteger(issue) || (issue as number) <= 0) return null
  if (typeof unit !== 'string' || unit === '' || typeof role !== 'string' || role === '') return null
  if (typeof store_root !== 'string' || store_root === '') return null
  return match as SagaUsageTarget
}

/** The effort a request asked for, as `usage add --effort` takes it. */
export function effortName(effort: string | number | undefined): string {
  return effort === undefined ? NO_EFFORT : String(effort)
}

/** The role a subagent's requests record: its saga role, else the session's. */
export function subagentRole(agentType: string | undefined, sessionRole: string): string {
  const saga = agentType === undefined ? null : SAGA_AGENT_TYPE.exec(agentType)
  return saga === null ? sessionRole : saga[1]
}

/** The session id an entry records: the session's own, or `<session>/<agent>` for a subagent's loop. */
export function entrySessionId(bucket: Pick<SagaUsageBucket, 'sessionId' | 'agentId'>): string {
  return bucket.agentId === null ? bucket.sessionId : `${bucket.sessionId}/${bucket.agentId}`
}

function sameEntry(a: Omit<UsageStep, 'uncachedInput' | 'cacheRead' | 'cacheWrite' | 'output'>, b: typeof a): boolean {
  return (
    a.sessionId === b.sessionId &&
    a.agentId === b.agentId &&
    a.role === b.role &&
    a.model === b.model &&
    a.effort === b.effort
  )
}

/** The queue with one request's usage summed into its bucket. */
export function addStep(queue: readonly SagaUsageBucket[], step: UsageStep): SagaUsageBucket[] {
  const at = queue.findIndex((bucket) => sameEntry(bucket, step))
  if (at < 0) return [...queue, { ...step, steps: 1 }]
  const was = queue[at]
  const sum: SagaUsageBucket = {
    ...was,
    uncachedInput: was.uncachedInput + step.uncachedInput,
    cacheRead: was.cacheRead + step.cacheRead,
    cacheWrite: was.cacheWrite + step.cacheWrite,
    output: was.output + step.output,
    steps: was.steps + 1,
  }
  return queue.map((bucket, i) => (i === at ? sum : bucket))
}

/**
 * The queue after `written` reached the record: its counts subtracted from its
 * bucket, which goes once nothing is left in it. What a request added while the
 * write ran stays.
 */
export function subtractWritten(queue: readonly SagaUsageBucket[], written: SagaUsageBucket): SagaUsageBucket[] {
  const out: SagaUsageBucket[] = []
  for (const bucket of queue) {
    if (!sameEntry(bucket, written)) {
      out.push(bucket)
      continue
    }
    const left: SagaUsageBucket = {
      ...bucket,
      uncachedInput: bucket.uncachedInput - written.uncachedInput,
      cacheRead: bucket.cacheRead - written.cacheRead,
      cacheWrite: bucket.cacheWrite - written.cacheWrite,
      output: bucket.output - written.output,
      steps: bucket.steps - written.steps,
    }
    if (left.steps > 0) out.push(left)
  }
  return out
}

/** The argv that appends one bucket to the target unit's usage block. */
export function usageAddArgv(pluginRoot: string, target: SagaUsageTarget, bucket: SagaUsageBucket): string[] {
  return sagaScriptArgv(pluginRoot, 'run_record.py', [
    '--store-root',
    target.store_root,
    'usage',
    'add',
    String(target.issue),
    '--unit',
    target.unit,
    '--session-id',
    entrySessionId(bucket),
    '--role',
    bucket.role,
    '--vendor',
    USAGE_VENDOR,
    '--model',
    bucket.model,
    '--effort',
    bucket.effort,
    '--uncached-input',
    String(bucket.uncachedInput),
    '--cache-read',
    String(bucket.cacheRead),
    CACHE_WRITE_FLAG,
    String(bucket.cacheWrite),
    '--output',
    String(bucket.output),
  ])
}

function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

// Module variables, on purpose: a hot reload stops the module's timers and
// resets these with them, so the next request starts the timer again. The
// queue itself is in `$.state` and survives the reload.
let timerRunning = false
let flushChain: Promise<void> = Promise.resolve()
let flushPending = false
const agentRoles = new Map<string, string>()

/** Write every bucket in the queue, one `usage add` each, stopping at the first failure. */
async function writeQueue($: EngineInterface, timeoutMs: number): Promise<void> {
  const target = await read($, usageTarget)
  if (target === null) return
  const queue = await read($, usageQueue)
  for (const bucket of queue ?? []) {
    let ran: ProcessResult
    try {
      ran = await $.process.run(usageAddArgv($.plugin.root, target, bucket), { timeoutMs })
    } catch (err) {
      $.ui.log(`usage-capture: usage add did not run: ${errorText(err)}`, { to: 'debug' })
      return
    }
    if (ran.exitCode !== 0) {
      $.ui.log(`usage-capture: usage add exited ${ran.exitCode}: ${ran.stderr.trim()}`, { to: 'debug' })
      return
    }
    await update($, usageQueue, (now) => subtractWritten(now ?? [], bucket))
  }
}

/** Queue one write of the queue after any already running, so two never interleave. */
function flushUsage($: EngineInterface, timeoutMs: number): Promise<void> {
  flushPending = true
  flushChain = flushChain
    .then(() => {
      flushPending = false
      return writeQueue($, timeoutMs)
    })
    .catch((err) => $.ui.log(`usage-capture: flush failed: ${errorText(err)}`, { to: 'debug' }))
  return flushChain
}

function startTimer($: EngineInterface): void {
  if (timerRunning) return
  timerRunning = true
  $.clock.every(USAGE_FLUSH_MS, () => {
    // A tick while a write is still waiting adds nothing: that write takes the whole queue.
    if (!flushPending) void flushUsage($, FLUSH_TIMEOUT_MS)
  })
}

/** The role a subagent's requests record, looked up once per subagent. */
async function roleOf($: EngineInterface, agentId: string, sessionRole: string): Promise<string> {
  const known = agentRoles.get(agentId)
  if (known !== undefined) return known
  let agentType: string | undefined
  try {
    agentType = (await $.agent.list()).find((agent) => agent.id === agentId)?.type
  } catch {
    agentType = undefined
  }
  const role = subagentRole(agentType, sessionRole)
  agentRoles.set(agentId, role)
  return role
}

export function registerUsageCapture(on: On): void {
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    let target: SagaUsageTarget | null = null
    try {
      target = parseUnitFor(await $.process.run(unitForArgv($.plugin.root, e.cwd), { timeoutMs: FLUSH_TIMEOUT_MS }))
    } catch (err) {
      $.ui.log(`usage-capture: unit-for did not run: ${errorText(err)}`, { to: 'debug' })
    }
    await update($, usageTarget, () => target)
    if (target !== null) {
      if (target.ambiguous) {
        $.ui.log(`usage-capture: several unit rows match; recording to #${target.issue} ${target.unit}`, { to: 'debug' })
      }
      startTimer($)
    }
    return next(e)
  })

  on('turn.step', { model: /^/ }, async function* ($, e, next) {
    const result = yield* next(e)
    const usage = result.usage
    // No response, or one without usage (interrupted, an API error): nothing was billed to read.
    if (usage === null) return result
    const target = await read($, usageTarget)
    if (target === null) return result
    const agentId = e.agentId ?? null
    const step: UsageStep = {
      sessionId: await $.session.id(),
      agentId,
      role: agentId === null ? target.role : await roleOf($, agentId, target.role),
      model: usage.model,
      effort: effortName(e.effort),
      uncachedInput: usage.input_tokens,
      cacheRead: usage.cache_read_input_tokens,
      cacheWrite: usage.cache_creation_input_tokens,
      output: usage.output_tokens,
    }
    await update($, usageQueue, (queue) => addStep(queue ?? [], step))
    startTimer($)
    return result
  })

  on('session.end', { sessionId: /^/ }, async ($, e, next) => {
    await flushUsage($, END_TIMEOUT_MS)
    return next(e)
  })
}

